using FarmWorking.Application.Abstractions; using FarmWorking.Domain.Entities; using FarmWorking.Infrastructure.Persistence; using Microsoft.EntityFrameworkCore;
namespace FarmWorking.Infrastructure.Repositories;
public class ProcessRepository(FarmDbContext db):IProcessRepository{public IReadOnlyList<WorkProcess> GetAll()=>db.WorkProcesses.AsNoTracking().Include(x=>x.Steps).Include(x=>x.Farms).OrderBy(x=>x.Name).ToList();public WorkProcess? Find(Guid id)=>db.WorkProcesses.Include(x=>x.Steps).Include(x=>x.Farms).FirstOrDefault(x=>x.Id==id);public void Add(WorkProcess item)=>db.WorkProcesses.Add(item);public void AddStep(ProcessStep step)=>db.ProcessSteps.Add(step);public void Remove(WorkProcess item)=>db.WorkProcesses.Remove(item);public Task SaveChangesAsync(CancellationToken ct=default)=>db.SaveChangesAsync(ct);}
